using System.Text.Json;using Microsoft.Extensions.Configuration;using Qms.Contracts.Trainings;using Qms.Infrastructure.Trainings;
namespace Qms.IntegrationTests;
public sealed class TrainingFinalReportTests
{
 [Fact]public async Task Completed_training_produces_immutable_visual_qa_pdf(){if(!File.Exists("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))return;var root=Path.Combine(Path.GetTempPath(),"qms-m05-pdf-tests",Guid.NewGuid().ToString("N"));var cfg=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"FileStorage:RootPath",root}}).Build();var now=new DateTimeOffset(2026,8,26,10,0,0,TimeSpan.Zero);var id=Guid.NewGuid();var qr=Guid.NewGuid();var employee=Guid.NewGuid();var position=Guid.NewGuid();var record=new TrainingRecordResponse(id,qr,"EGT-2026-000999",null,Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),employee,"Zeynep Arslan",position,"Dolum Operatörü","SOP-PRD-014","Dolum hattı sıcaklık izleme eğitimi","SOP-PRD-014","1.0","ExamAndPractical","Hybrid",80,12,3,true,2026,"OTR-2026-041","Tolga Erdem",now.AddDays(-2),"Completed",100,now.AddDays(-10),now.AddDays(-9),"Dokümanı okudum, anladım ve uygulayacağım.",now,now.AddMonths(12),"Sınav ve saha gözlemi uygundur.",now.AddDays(-12),now,8);var attempts=new[]{new TrainingAttemptResponse(Guid.NewGuid(),1,72,true,false,"EGT-F-01 ilk sınav","Tolga Erdem",now.AddDays(-5)),new TrainingAttemptResponse(Guid.NewGuid(),2,92,true,true,"EGT-F-01 tekrar sınav ve saha gözlemi","Tolga Erdem",now.AddDays(-2))};var audit=new[]{new TrainingAuditResponse(Guid.NewGuid(),1,"TrainingAssignmentCreated","Gizem Tunç",now.AddDays(-12),null,JsonDocument.Parse("{}").RootElement.Clone()),new TrainingAuditResponse(Guid.NewGuid(),8,"TrainingStatusChanged","Tolga Erdem",now,"Yeterlilik onayı",JsonDocument.Parse("{}").RootElement.Clone())};var signs=new[]{new TrainingSignatureResponse(Guid.NewGuid(),3,employee,"Zeynep Arslan","Dokümanı okudum ve anladım",now.AddDays(-9),new string('a',64),null),new TrainingSignatureResponse(Guid.NewGuid(),7,Guid.NewGuid(),"Tolga Erdem","Eğitim değerlendirmesi",now.AddDays(-2),new string('b',64),"Başarılı"),new TrainingSignatureResponse(Guid.NewGuid(),8,Guid.NewGuid(),"Tolga Erdem","Eğitim yeterlilik onayı",now,new string('c',64),"Uygun")};var details=new TrainingDetailsResponse(record,attempts,audit,signs,[],[]);var service=new TrainingFinalReportService(cfg);var first=await service.EnsureGeneratedAsync(details,CancellationToken.None);var second=await service.EnsureGeneratedAsync(details,CancellationToken.None);Assert.True(first.Content.Length>5000);Assert.Equal(first.Sha256,second.Sha256);Assert.Equal(first.Content,second.Content);var output=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../../output/pdf/M05-training-visual-qa.pdf"));Directory.CreateDirectory(Path.GetDirectoryName(output)!);await File.WriteAllBytesAsync(output,first.Content);}
}
